'use strict';
const "'$ = s => document.querySelector(s);
const esc = v => String(v).replace(/[&<>"'"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
const rooms=[['Workshop room',18],['Gallery',24],['Courtyard',30]];
const palette=[['#9e5543','#f5e3dc'],['#657748','#e9eedf'],['#637c95','#e3ebf0']];
const key='museum-arrivals-v1';
const seed={bookings:[
 {id:'school',name:'School group',arrival:600,total:28,groups:[{id:'a',name:'School A',n:14},{id:'b',name:'School B',n:14}]},
 {id:'club',name:'Club',arrival:630,total:14,groups:[{id:'c',name:'Club group',n:14}]},
 {id:'family',name:'Family group',arrival:660,total:9,groups:[{id:'f',name:'Family group',n:9}]}
],activities:[['a',600,0],['b',600,1],['b',630,0],['a',630,1],['c',630,2],['f',660,0],['c',660,1]].map(([group,start,room],i)=>({id:'s'+i,group,start,room}))};
let state=structuredClone(seed),saveMessage='Draft saved on this device';
try{const saved=localStorage.getItem(key);if(saved)state=JSON.parse(saved);else localStorage.setItem(key,JSON.stringify(state))}catch{saveMessage='Local saving unavailable · keep this window open'}
const uid=()=>crypto.randomUUID();
const time=m=>[Math.floor(m/60),m%60].map(x=>String(x).padStart(2,'0')).join(':');
const minutes=s=>Number(s.slice(0,2))*60+Number(s.slice(3));
const color=i=>{const [a,t]=palette[i%palette.length];return '--accent:'+a+';--tint:'+t};
function entries(){
 const groups=new Map();
 state.bookings.forEach((b,i)=>b.groups.forEach(g=>groups.set(g.id,{b,g,i})));
 return state.activities.map(a=>({...a,...groups.get(a.group),warnings:[]})).sort((a,b)=>a.start-b.start||a.room-b.room);
}
function inspect(rows){
 for(const a of rows){
  const overlap=rows.filter(b=>b.id"'!==a.id&&a.start<b.start+30&&b.start<a.start+30);
  if(a.start<a.b.arrival)a.warnings.push('"'Starts before arrival at '+time(a.b.arrival));
  if(overlap.some(b=>b.group===a.group))a.warnings.push('Subgroup double-booked');
  const same=overlap.filter(b=>b.room===a.room);
  if(same.length)a.warnings.push('Space double-booked');
  const peak=Math.max(...[a.start,...same.map(b=>Math.max(a.start,b.start))].map(t=>a.g.n+same.filter(b=>b.start<=t&&t<b.start+30).reduce((n,b)=>n+b.g.n,0)));
  if(peak>rooms[a.room][1])a.warnings.push(peak+' visitors exceed capacity '+rooms[a.room][1]);
 }
}
function render(){
 const rows=entries();inspect(rows);
 const notices=rows.filter(a=>a.warnings.length).map(a=>time(a.start)+' · '+a.b.name+' / '+a.g.name+' · '+rooms[a.room][0]+' — '+a.warnings.join(', '));
 for(const b of state.bookings)for(const g of b.groups)if("'!rows.some(a=>a.group===g.id))notices.push(b.name+'"' / '+g.name+' has no activity assigned.');
 const count=state.bookings.reduce((n,b)=>n+b.total,0);
 "'$('"'#summary').innerHTML='<span><b>'+state.bookings.length+'</b> bookings</span><span><b>'+count+'</b> visitors</span><span><b>'+rows.length+'</b> activities</span><span class=\"status '+(notices.length?'warn':'')+'\">'+(notices.length?'⚠ Schedule needs attention':'✓ No scheduling conflicts')+'</span>';
 "'$('"'#bookings').innerHTML=state.bookings.map((b,i)=>'<button class=\"card\" data-act=\"booking\" data-id=\"'+b.id+'\" style=\"'+color(i)+'\"><span class=\"tag\"><i class=\"dot\"></i>Arrival</span><span class=\"time\">'+time(b.arrival)+'</span><h3>'+esc(b.name)+'</h3><small>'+b.total+' visitors · '+b.groups.length+' subgroup'+(b.groups.length===1?'':'s')+'</small><span class=\"arrow\" aria-hidden=\"true\">↗</span></button>').join('');
 "'$('"'#issues').innerHTML=notices.length?'<ul>'+notices.map(n=>'<li>'+esc(n)+'</li>').join('')+'</ul>':'';
 const times=[...new Set(rows.map(a=>a.start))];
 "'$('"'#board').innerHTML='<thead><tr><th scope=\"col\">Start</th>'+rooms.map(([r,n])=>'<th scope=\"col\">'+r+'<small>'+n+' visitors max</small></th>').join('')+'</tr></thead><tbody>'+times.map(t=>'<tr><th scope=\"row\">'+time(t)+'</th>'+rooms.map((_,i)=>'<td>'+(rows.filter(a=>a.start===t&&a.room===i).map(a=>'<button class=\"slot\" data-act=\"activity\" data-id=\"'+a.id+'\" style=\"'+color(a.i)+'\">'+esc(a.g.name)+'<span>'+a.g.n+' visitors · '+time(a.start)+'–'+time(a.start+30)+'</span>'+(a.warnings.length?'<span class=\"flag\">⚠ Conflict</span>':'')+'</button>').join('')||'<span class=\"empty\">—</span>')+'</td>').join('')+'</tr>').join('')+'</tbody>';
 "'$('"'#save').textContent=saveMessage;
 const table=(heads,body)=>'<table><thead><tr>'+heads.map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+body.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join('')+'</tr>').join('')+'</tbody></table>';
 "'$('"'#paper').innerHTML='<p>Museum / Education desk</p><h1>Front-desk schedule</h1><h2>Group arrivals</h2>'+table(['Arrival','Booking','Visitors','Subgroups'],[...state.bookings].sort((a,b)=>a.arrival-b.arrival).map(b=>[time(b.arrival),b.name,b.total,b.groups.map(g=>g.name+' ('+g.n+')').join(', ')]))+'<h2>Activities by time</h2>'+table(['Time','Booking','Subgroup','Visitors','Space'],rows.map(a=>[time(a.start)+'–'+time(a.start+30),a.b.name,a.g.name,a.g.n,rooms[a.room][0]]))+(notices.length?'<h2>Schedule needs attention</h2>'+"'$('"'#issues').innerHTML:'');
}
const dialog="'$('"'dialog');
let active,editing;
function field(label,input){return '<label>'+label+input+'</label>'}
const input=(name,type,value,attrs='')=>'<input required name=\"'+name+'\" type=\"'+type+'\" value=\"'+esc(value)+'\" '+attrs+'>';
function groupRow(g){return '<div class=\"sg\" data-id=\"'+g.id+'\">'+field('Subgroup name',input('gname','text',g.name,'maxlength=\"60\"'))+field('Visitors',input('n','number',g.n,'min=\"1\" max=\"9999\"'))+'<button type=\"button\" data-act=\"removeGroup\" aria-label=\"Remove subgroup\">×</button></div>'}
function openEditor(kind,id){
 active=kind;editing=id;"'$('"'#error').textContent='';
 if(kind==='booking'){
 const b=state.bookings.find(b=>b.id===id)||{name:'',total:1,arrival:600,groups:[{id:uid(),name:'Whole group',n:1}]};
 "'$('"'#title').textContent=id?'Edit booking':'Add booking';
 "'$('"'#fields').innerHTML=field('Booking name',input('bname','text',b.name,'maxlength=\"60\"'))+field('Arrival time',input('arrival','time',time(b.arrival)))+(id?'<label class=\"check\"><input type=\"checkbox\" name=\"shift\" checked> Move activities by the same time change</label>':'')+field('Total visitors',input('total','number',b.total,'min=\"1\" max=\"9999\"'))+'<fieldset><legend>Named subgroups</legend><p class=\"hint\">Subgroup sizes must add up to the booking total.</p><div id=\"groups\">'+b.groups.map(groupRow).join('')+'</div><button class=\"minor\" type=\"button\" data-act=\"addGroup\">+ Add subgroup</button></fieldset>';
 }else{
 const a=state.activities.find(a=>a.id===id)||{group:state.bookings[0].groups[0].id,start:state.bookings[0].arrival,room:0};
 "'$('"'#title').textContent=id?'Edit activity':'Assign activity';
 "'$('"'#fields').innerHTML=field('Booking / subgroup','<select name=\"group\">'+state.bookings.map(b=>'<optgroup label=\"'+esc(b.name)+'\">'+b.groups.map(g=>'<option value=\"'+g.id+'\" '+(a.group===g.id?'selected':'')+'>'+esc(b.name)+' / '+esc(g.name)+' ('+g.n+')</option>').join('')+'</optgroup>').join('')+'</select>')+field('Start time',input('start','time',time(a.start),'max=\"23:30\"'))+'<p class=\"hint\" id=\"timing\"></p>'+field('Space','<select name=\"room\">'+rooms.map(([r,n],i)=>'<option value=\"'+i+'\" '+(a.room===i?'selected':'')+'>'+r+' · '+n+' visitors max</option>').join('')+'</select>')+(id?'<button type=\"button\" class=\"danger minor\" data-act=\"removeActivity\">Remove activity</button>':'');
 timing();
 }
 dialog.showModal();
}
function timing(){const f="'$('"'#form').elements,b=state.bookings.find(b=>b.groups.some(g=>g.id===f.group.value));"'$('"'#timing').textContent='Arrival '+time(b.arrival)+(f.start.value?' · Activity ends '+time(minutes(f.start.value)+30):'')}
function commit(){
 try{localStorage.setItem(key,JSON.stringify(state));saveMessage='Draft saved on this device'}catch{saveMessage='Local saving unavailable · keep this window open'}
 render();dialog.close();
}
document.addEventListener('click',e=>{
 const btn=e.target.closest('button[data-act]');if("'!btn)return;
 const act=btn.dataset.act;
 if(act==='"'close')dialog.close();
 if(act==='booking'||act==='activity')openEditor(act,btn.dataset.id);
 if(act==='print')window.print();
 if(act==='addGroup'){"'$('"'#groups').insertAdjacentHTML('beforeend',groupRow({id:uid(),name:'',n:1}));"'$('"'#groups .sg:last-child input').focus()}
 if(act==='removeGroup'){
 const row=btn.closest('.sg');if(state.activities.some(a=>a.group===row.dataset.id))"'$('"'#error').textContent='Reassign or remove this subgroup’s activities before removing it.';else row.remove();
 }
 if(act==='removeActivity'){state.activities=state.activities.filter(a=>a.id"'!==editing);commit()}
});
$('"'#form').addEventListener('input',()=>{if(active==='activity')timing();"'$('"'#error').textContent=''});
"'$('"'#form').addEventListener('submit',e=>{
 e.preventDefault();const f=e.target.elements;
 const fail=msg=>"'$('"'#error').textContent=msg;
 if(active==='booking'){
 const groups=[...document.querySelectorAll('.sg')].map(row=>({id:row.dataset.id,name:row.querySelector('[name=gname]').value.trim(),n:Number(row.querySelector('[name=n]').value)}));
 const b={id:editing||uid(),name:f.bname.value.trim(),total:Number(f.total.value),arrival:minutes(f.arrival.value),groups};
 if("'!b.name||groups.some(g=>!g.name))return fail('"'Enter a name for the booking and each subgroup.');
 if(new Set(groups.map(g=>g.name.toLowerCase())).size"'!==groups.length)return fail('"'Give each subgroup a distinct name.');
 if(groups.reduce((n,g)=>n+g.n,0)"'!==b.total)return fail('"'Subgroup sizes must add up to '+b.total+' visitors.');
 if(editing){
 const i=state.bookings.findIndex(b=>b.id===editing);
 const delta=f.shift.checked?b.arrival-state.bookings[i].arrival:0;
 const affected=state.activities.filter(a=>groups.some(g=>g.id===a.group));
 if(affected.some(a=>a.start+delta<0||a.start+delta+30>1440))return fail('Moving activities would cross midnight. Keep their times or choose another arrival.');
 affected.forEach(a=>a.start+=delta);state.bookings[i]=b;
 }else state.bookings.push(b);
 }else{
 const a={id:editing||uid(),group:f.group.value,start:minutes(f.start.value),room:Number(f.room.value)};
 if(editing)state.activities[state.activities.findIndex(x=>x.id===editing)]=a;else state.activities.push(a);
 }
 commit();
});
render();
